/* Source-informed original learning path. Guest-first and local-only progress. */
(function(root,factory){const api=factory(root);if(typeof module==='object'&&module.exports)module.exports=api;root.SVCurriculum=api;})(typeof window!=='undefined'?window:globalThis,function(root){
  'use strict';
  const KEY='smartvio-curriculum-progress-v1',LANGS=['zh','en','ja','de'],LEVELS=['all','zero','beginner','intermediate','advanced'],FEATURES=['learn','studio','tuner','metronome'];
  const words={
    eyebrow:['一步一步，拉出你的声音','YOUR NEXT LITTLE STEP','一歩ずつ、自分の音へ','DEIN NÄCHSTER KLEINER SCHRITT'],title:['找到适合你的下一步','A path at your pace','自分のペースで進もう','Dein Weg, dein Tempo'],intro:['选一个小目标，看示范、慢练，再回听自己。原有课程和功能都可以继续使用。','Choose one small goal: watch, practise slowly, then listen back. Your existing courses and tools are still here.','小さな目標を一つ選び、見て、ゆっくり練習し、自分の音を聴き直します。これまでの教材や機能も使えます。','Wähle ein kleines Ziel: ansehen, langsam üben und nachhören. Bisherige Kurse und Werkzeuge bleiben verfügbar.'],
    all:['全部阶段','All stages','すべて','Alle Stufen'],zero:['零基础','Starting out','はじめて','Erste Schritte'],beginner:['初级','Beginner','初級','Grundlagen'],intermediate:['中级','Intermediate','中級','Aufbau'],advanced:['进阶','Advanced','応用','Vertiefung'],guest:['无需登录 · 进度保存在本机','No sign-in · progress stays on this device','ログイン不要・進捗はこの端末に保存','Ohne Anmeldung · Fortschritt auf diesem Gerät'],saved:['进度已保存到此浏览器','Progress saved in this browser','このブラウザーに保存済み','Fortschritt in diesem Browser gespeichert'],volatile:['浏览器无法保存；本次进度仅临时保留，可先导出。','Browser storage is unavailable. Progress is temporary; export it to keep a copy.','保存できません。進捗は一時的です。エクスポートで控えを保存できます。','Browserspeicher nicht verfügbar. Der Fortschritt ist vorläufig; exportiere eine Kopie.'],corrupt:['原进度无法读取，已保留原数据；本次进度可导出。明确清除后才能重新保存。','Previous progress could not be read and has been preserved. Export this session; clear explicitly before saving again.','以前の進捗を読めませんが、元のデータは残しています。今回分を出力できます。明示的に消去すると再保存できます。','Frühere Daten sind nicht lesbar und bleiben erhalten. Exportiere diese Sitzung; erst nach bewusstem Löschen wird wieder gespeichert.'],
    appGuide:['原有六步按钮教学','Original six-step app tour','これまでの6ステップ操作ガイド','Bisherige Einführung in sechs Schritten'],export:['导出我的进度','Export my progress','進捗をエクスポート','Fortschritt exportieren'],clear:['清除此路径的本机进度','Clear this path’s local progress','この学習パスの進捗を消去','Lokalen Fortschritt dieses Pfads löschen'],clearAsk:['仅清除八阶段路径进度？原课程、录音和其他资料会保留。','Clear only this eight-stage path? Existing courses, recordings and other data will stay.','この8段階の進捗だけを消去しますか？以前の教材・録音・他のデータは残ります。','Nur diesen achtstufigen Pfad löschen? Bisherige Kurse, Aufnahmen und andere Daten bleiben erhalten.'],confirmClear:['确认清除','Confirm clear','消去を確認','Löschen bestätigen'],cancel:['取消','Cancel','キャンセル','Abbrechen'],cleared:['此路径的进度已清除','This path’s progress was cleared','このパスの進捗を消去しました','Fortschritt dieses Pfads gelöscht'],
    self:['完成状态由你自评，不等于考试等级或动作认证。','Completion is your self-review, not an exam grade or a technique certification.','完了は自己確認です。試験の級や技術認定ではありません。','Der Abschluss ist eine Selbsteinschätzung, keine Prüfungsstufe oder Technikzertifizierung.'],done:['我已练过','Practised','練習済み','Geübt'],start:['看看这一阶段','Explore this stage','この段階を見る','Diese Stufe ansehen'],continue:['继续这个目标','Continue this goal','この目標を続ける','Dieses Ziel fortsetzen'],back:['所有阶段','All stages','すべての段階','Alle Stufen'],watch:['先看清楚','Watch and notice','まず観察する','Ansehen und wahrnehmen'],practice:['慢慢跟练','Practise slowly','ゆっくり練習','Langsam üben'],review:['回听与自评','Listen back and reflect','聴き直して振り返る','Nachhören und reflektieren'],
    animation:['打开原创动画示范','Open the original animated guide','オリジナルのアニメを見る','Eigene Animation öffnen'],follow:['进入同步跟练','Open guided practice','連動練習を開く','Begleitetes Üben öffnen'],reference:['官方参考研习','Study official references','公式資料で学ぶ','Offizielle Quellen studieren'],referenceOnly:['本阶段以教师来源与自评为主。高把位、双音与跳弓不在当前动画和自动反馈范围内。','This stage uses teacher references and self-review. Higher positions, double stops and spiccato are outside the current animation and automatic feedback.','この段階は先生の資料と自己確認が中心です。高いポジション・重音・スピッカートは現在のアニメと自動フィードバックの対象外です。','Diese Stufe nutzt Lehrquellen und Selbstreflexion. Höhere Lagen, Doppelgriffe und Spiccato liegen außerhalb der aktuellen Animation und automatischen Rückmeldung.'],
    sourceTitle:['带着问题，看老师的示范','Watch a teacher with a question in mind','問いを持って先生の手本を見る','Mit einer Frage Lehrbeispiele ansehen'],sourceNote:['点击后前往原作者网站；部分是图文资料。视频语言、可用地区和访问条件由来源决定。','Open the creator’s website; some sources are illustrated articles. Video language, region availability and access conditions depend on the source.','クリックすると作者のサイトへ移動します。一部は図文資料です。言語・地域制限・利用条件は配信元によります。','Öffnet die Website des Urhebers; einige Quellen sind bebilderte Artikel. Sprache, Verfügbarkeit und Zugang hängen von der Quelle ab.'],sourceOpen:['打开官方来源 ↗','Open official source ↗','公式資料を開く ↗','Offizielle Quelle öffnen ↗'],historical:['历史教学示范，非现行考试要求','Historical demonstration, not current exam requirements','過去の手本です。現行の試験要件ではありません','Historisches Lehrbeispiel, keine aktuellen Prüfungsanforderungen'],
    rights:['第三方视频与谱面保留在原站；这里只提供来源链接和原创学习任务。','Third-party video and scores stay at the source; this page provides links and original learning tasks.','第三者の動画や楽譜は元サイトにあります。ここではリンクと独自の学習課題を提供します。','Fremde Videos und Noten bleiben auf der Quellseite; hier stehen Links und eigene Lernaufgaben.'],
    check:['我已围绕这个目标练习并做过回听或自评','I practised this goal and listened back or reflected','この目標を練習し、聴き直しまたは振り返りをしました','Ich habe dieses Ziel geübt und nachgehört oder reflektiert'],mark:['记录为我已练过','Mark as practised','練習済みとして記録','Als geübt markieren'],unmark:['撤销已练过标记','Undo practised mark','練習済みを取り消す','Markierung zurücknehmen'],checkFirst:['请先确认你自己的练习与回顾','Please confirm your own practice and reflection first','まず自分の練習と振り返りを確認してください','Bestätige zuerst deine Übung und Reflexion'],next:['下一阶段','Next stage','次の段階','Nächste Stufe'],previous:['上一步','Previous step','前の手順','Voriger Schritt'],nextStep:['下一步','Next step','次の手順','Nächster Schritt'],studio:['去录音与回听','Record and listen back','録音して聴き直す','Aufnehmen und nachhören'],tuner:['打开调音器','Open tuner','チューナーを開く','Stimmgerät öffnen'],metronome:['打开节拍器','Open metronome','メトロノームを開く','Metronom öffnen'],unavailable:['这个入口暂时不可用，请返回重试。','This entry is unavailable. Go back and retry.','この入口は現在使えません。戻って再試行してください。','Dieser Einstieg ist nicht verfügbar. Gehe zurück und versuche es erneut.'],invalid:['学习目录暂时不可用，请稍后重试。','The learning path is unavailable. Please retry later.','学習パスを利用できません。後で再試行してください。','Der Lernpfad ist nicht verfügbar. Bitte später erneut versuchen.'],exportFail:['导出未完成，请允许浏览器下载后重试。','Export did not finish. Allow browser downloads and retry.','出力できません。ブラウザーのダウンロードを許可して再試行してください。','Export unvollständig. Erlaube Browserdownloads und versuche es erneut.'],progress:['已自评练过 {n} / 8 个阶段','Self-reviewed: {n} / 8 stages','自己確認済み：{n} / 8段階','Selbst geprüft: {n} / 8 Stufen'],step:['步骤 {n} / 3','Step {n} / 3','手順 {n} / 3','Schritt {n} / 3']
  };
  const clone=v=>JSON.parse(JSON.stringify(v)),E=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x])),local=(v,lang)=>v?.[lang]||v?.en||'';
  function text(lang,key,args={}){let value=words[key]?.[Math.max(0,LANGS.indexOf(lang))]||key;for(const[k,v]of Object.entries(args))value=value.replaceAll('{'+k+'}',String(v));return value;}
  function initial(){return {schema:1,lastStageId:null,level:'all',stages:{}};}
  function safeURL(value){try{const url=new URL(value);if(url.protocol!=='https:'||url.username||url.password)return '';const allowed=['www.benedettifoundation.org','www.yamaha.com','jp.yamaha.com','www.trinitycollege.com','trinitycollege.com','www.violinlounge.com','www.classicfm.com','www.abrsm.org'];return allowed.includes(url.hostname)?url.href:'';}catch{return '';}}
  function validateData(value){if(value?.schema!==1||!Array.isArray(value.stages)||value.stages.length!==8||!Array.isArray(value.resources)||value.resources.length>100)throw Error('Invalid curriculum');const ids=new Set(),orders=new Set(),res=new Set();for(const r of value.resources){if(!/^[a-z][a-z0-9-]{1,63}$/.test(r.id)||res.has(r.id)||!safeURL(r.url)||typeof r.title!=='string'||typeof r.author!=='string'||!LANGS.every(l=>typeof r.topic?.[l]==='string'&&r.topic[l].length<500))throw Error('Invalid resource');res.add(r.id);}for(const s of value.stages){if(!/^[a-z][a-z0-9-]{1,63}$/.test(s.id)||ids.has(s.id)||!LEVELS.slice(1).includes(s.level)||!Number.isInteger(s.order)||s.order<1||s.order>8||orders.has(s.order)||!LANGS.every(l=>typeof s.title?.[l]==='string'&&typeof s.summary?.[l]==='string')||!Array.isArray(s.steps)||s.steps.length!==3||!s.steps.every((x,i)=>x.id===['watch','practice','review'][i]&&LANGS.every(l=>typeof x.text?.[l]==='string'))||!Array.isArray(s.resources)||!s.resources.every(id=>res.has(id))||!Array.isArray(s.tools)||!s.tools.every(x=>FEATURES.includes(x))||!(s.lessonId===null||['settle','open-strings','first-fingers','crossing','dawn-melody','vibrato'].includes(s.lessonId)))throw Error('Invalid stage');ids.add(s.id);orders.add(s.order);}return clone(value);}
  function validateProgress(value,stageIds){if(!value||value.schema!==1||!LEVELS.includes(value.level)||!(value.lastStageId===null||stageIds.includes(value.lastStageId))||!value.stages||typeof value.stages!=='object'||Array.isArray(value.stages)||Object.keys(value.stages).length>8)throw Error('Invalid progress');for(const[id,item]of Object.entries(value.stages)){if(!stageIds.includes(id)||!item||typeof item!=='object'||!Number.isInteger(item.step)||item.step<0||item.step>2||typeof item.reviewed!=='boolean'||typeof item.completed!=='boolean'||(item.completed&&!item.reviewed))throw Error('Invalid stage progress');}return clone(value);}
  function create(options={}){
    const env=options.environment||root;let data,host=null,lang='zh',selectedId=null,level='all',clearPending=false,storage=null,storageState='saved',rawCorrupt=null,progress=initial();try{data=validateData(options.data||env.SVCurriculumData);}catch{data=null;}
    try{storage=options.storage||env.localStorage;if(!storage)storageState='volatile';else{const raw=storage.getItem(KEY);if(raw!==null){try{if(raw.length>131072)throw Error('Large progress');progress=validateProgress(JSON.parse(raw),data?.stages.map(s=>s.id)||[]);}catch{storageState='corrupt';rawCorrupt=raw;}}}}catch{storageState='volatile';}
    level=progress.level;
    const t=(key,args)=>text(lang,key,args),notice=message=>{if(typeof options.notify==='function')options.notify(message);},find=()=>data?.stages.find(s=>s.id===selectedId),record=id=>progress.stages[id]||{step:0,reviewed:false,completed:false};
    function persist(){if(storageState==='corrupt')return false;try{if(!storage)throw Error('No storage');storage.setItem(KEY,JSON.stringify(progress));storageState='saved';return true;}catch{storageState='volatile';return false;}}
    function touch(){if(!selectedId)return;progress.lastStageId=selectedId;progress.stages[selectedId]=record(selectedId);persist();}
    function badge(s){return '<span class="svcu-level">'+E(t(s.level))+'</span>';}
    function art(index){const glyphs=["<path d=\"M113 31h14v51c20 3 16 22 7 26 15 19 4 34-14 34s-29-15-14-34c-9-4-13-23 7-26V31zm-7 2h28m-23 57h18m-17 27h16M118 31v102m4-102v102\"/>","<path d=\"M74 40v84m30-84v84m30-84v84m30-84v84M64 53h110M64 111h110\"/><path d=\"M104 40v84\" stroke-width=\"7\"/><text x=\"69\" y=\"145\">G</text><text x=\"98\" y=\"145\">D</text><text x=\"128\" y=\"145\">A</text><text x=\"158\" y=\"145\">E</text>","<path d=\"M92 33v98m18-98v98m18-98v98m18-98v98M83 51h72m-72 30h72m-72 30h72\"/><circle cx=\"110\" cy=\"51\" r=\"8\"/><circle cx=\"128\" cy=\"81\" r=\"8\"/><circle cx=\"146\" cy=\"111\" r=\"8\"/>","<path d=\"M81 34v100m28-100v100m28-100v100m28-100v100M65 108c20-75 39-75 58-14s37 32 53-35m-12 5 12-5 1 14\"/>","<path d=\"M58 57h124M58 71h124M58 85h124M58 99h124M58 113h124m-96-8V50l60-9v51m-60-32 60-9\"/><ellipse cx=\"78\" cy=\"105\" rx=\"9\" ry=\"6\"/><ellipse cx=\"138\" cy=\"92\" rx=\"9\" ry=\"6\"/>","<path d=\"M61 90c10-58 20-58 30 0s20 58 30 0 20-58 30 0 20 58 30 0M61 90h120\"/>","<path d=\"M94 33v100m17-100v100m17-100v100m17-100v100m24-14V47m-12 13 12-13 12 13m-73 18h34\"/><circle cx=\"119\" cy=\"98\" r=\"9\"/><circle cx=\"119\" cy=\"60\" r=\"5\"/>","<path d=\"M67 108V57m52 51V50m52 58V42M57 129h124\"/><ellipse cx=\"58\" cy=\"110\" rx=\"10\" ry=\"6\"/><ellipse cx=\"110\" cy=\"110\" rx=\"10\" ry=\"6\"/><ellipse cx=\"162\" cy=\"110\" rx=\"10\" ry=\"6\"/><path d=\"M58 35h8m44-8h8m43-8h8\"/>"];return '<svg class="svcu-art" viewBox="0 0 240 160" aria-hidden="true"><path d="M-20 137C40 72 95 186 158 96S252 49 266 116"/><text class="cu-order" x="19" y="34">'+String(index+1).padStart(2,'0')+'</text><g class="cu-symbol" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">'+glyphs[index%glyphs.length]+'</g></svg>'; }
    function status(){return '<p class="svcu-storage" role="status">'+E(t(storageState))+'</p>';}
    function footer(){return '<footer class="svcu-footer"><p>'+E(t('self'))+'</p>'+status()+'<div class="svcu-actions"><button type="button" data-cu-feature="learn">'+E(t('appGuide'))+'</button><button type="button" data-cu-action="export">'+E(t('export'))+'</button><button type="button" class="svcu-subtle" data-cu-action="clear">'+E(t('clear'))+'</button></div>'+(clearPending?'<div class="svcu-clear" role="group" aria-label="'+E(t('clear'))+'"><p>'+E(t('clearAsk'))+'</p><button type="button" data-cu-action="confirm-clear">'+E(t('confirmClear'))+'</button><button type="button" data-cu-action="cancel-clear">'+E(t('cancel'))+'</button></div>':'')+'</footer>';}
    function list(){const count=Object.values(progress.stages).filter(x=>x.completed).length,visible=data.stages.filter(s=>level==='all'||s.level===level);return '<section class="svcu-list"><header class="svcu-head"><span class="svcu-eyebrow">'+E(t('eyebrow'))+'</span><h2>'+E(t('title'))+'</h2><p>'+E(t('intro'))+'</p><div class="svcu-meta"><span>'+E(t('guest'))+'</span><span>'+E(t('progress',{n:count}))+'</span></div></header><nav class="svcu-filters" aria-label="'+E(t('all'))+'">'+LEVELS.map(x=>'<button type="button" data-cu-level="'+x+'" aria-pressed="'+(level===x)+'">'+E(t(x))+'</button>').join('')+'</nav><div class="svcu-grid">'+visible.map(s=>{const p=progress.stages[s.id];return '<button type="button" class="svcu-card svcu-theme-'+s.level+'" data-cu-select="'+s.id+'">'+art(s.order-1)+'<span class="svcu-card-copy">'+badge(s)+'<strong>'+E(local(s.title,lang))+'</strong><span>'+E(local(s.summary,lang))+'</span><small>'+E(t(p?.completed?'done':p?'continue':'start'))+' <span aria-hidden="true">↗</span></small></span></button>';}).join('')+'</div>'+footer()+'</section>';}
    function sources(stage){return '<section class="svcu-sources" id="svcu-sources"><h3>'+E(t('sourceTitle'))+'</h3><p>'+E(t('sourceNote'))+'</p><div class="svcu-source-grid">'+stage.resources.map(id=>{const r=data.resources.find(x=>x.id===id);return '<article class="svcu-source"><span class="svcu-source-language">'+E(r.language==='ja'?'日本語':'English')+'</span><h4>'+E(local(r.topic,lang))+'</h4><p>'+E(r.title)+'</p><small>'+E(r.author)+'</small>'+(r.historical?'<small>'+E(t('historical'))+'</small>':'')+'<a href="'+E(safeURL(r.url))+'" target="_blank" rel="noopener noreferrer">'+E(t('sourceOpen'))+'</a></article>';}).join('')+'</div><p class="svcu-rights">'+E(t('rights'))+'</p></section>';}
    function detail(){const s=find(),p=record(s.id),step=s.steps[p.step];return '<section class="svcu-detail"><header class="svcu-detail-head"><button type="button" data-cu-action="back">← '+E(t('back'))+'</button>'+badge(s)+'<h2 tabindex="-1" data-cu-heading>'+E(local(s.title,lang))+'</h2><p>'+E(local(s.summary,lang))+'</p></header><nav class="svcu-steps" aria-label="'+E(t('step',{n:p.step+1}))+'">'+s.steps.map((x,i)=>'<button type="button" data-cu-step="'+i+'"'+(i===p.step?' aria-current="step"':'')+'><span>'+(i+1)+'</span>'+E(t(x.id))+'</button>').join('')+'</nav><article class="svcu-task"><span class="svcu-eyebrow">'+E(t('step',{n:p.step+1}))+'</span><h3>'+E(t(step.id))+'</h3><p>'+E(local(step.text,lang))+'</p>'+(!s.lessonId?'<p class="svcu-reference-note">'+E(t('referenceOnly'))+'</p>':'')+'<div class="svcu-actions">'+(p.step<2&&s.lessonId?'<button type="button" class="svcu-primary" data-cu-lesson="'+s.lessonId+'">'+E(t(p.step===0?'animation':'follow'))+'</button>':p.step===2?'<button type="button" class="svcu-primary" data-cu-feature="studio">'+E(t('studio'))+'</button>':'<button type="button" class="svcu-primary" data-cu-action="sources">'+E(t('reference'))+'</button>')+s.tools.filter(x=>!(p.step===2&&x==='studio')).map(x=>'<button type="button" data-cu-feature="'+x+'">'+E(t(x))+'</button>').join('')+'</div><div class="svcu-task-nav"><button type="button" data-cu-step="'+Math.max(0,p.step-1)+'"'+(p.step===0?' disabled':'')+'>'+E(t('previous'))+'</button><button type="button" data-cu-step="'+Math.min(2,p.step+1)+'"'+(p.step===2?' disabled':'')+'>'+E(t('nextStep'))+'</button></div></article>'+sources(s)+'<section class="svcu-review"><label><input type="checkbox" data-cu-reviewed'+(p.reviewed?' checked':'')+'> <span>'+E(t('check'))+'</span></label><p>'+E(t('self'))+'</p><div class="svcu-actions"><button type="button" data-cu-action="complete"'+(!p.reviewed&&!p.completed?' disabled':'')+'>'+E(t(p.completed?'unmark':'mark'))+'</button>'+(s.order<8?'<button type="button" data-cu-select="'+data.stages.find(x=>x.order===s.order+1).id+'">'+E(t('next'))+' →</button>':'')+'</div></section>'+footer()+'</section>';}
    function draw(focus=false){if(!host)return;host.innerHTML='<div class="svcu" data-i18n-ignore>'+(!data?'<p role="status">'+E(t('invalid'))+'</p>':selectedId?detail():list())+'</div>';if(focus)host.querySelector?.('[data-cu-heading]')?.focus?.({preventScroll:true});}
    function select(id){if(!data?.stages.some(s=>s.id===id))return false;selectedId=id;clearPending=false;touch();draw(true);return true;}
    async function navigate(type,id){touch();if(type==='lesson'){if(!data?.stages.some(x=>x.lessonId===id))return;if(typeof options.onNavigateLesson!=='function'){notice(t('unavailable'));return;}await options.onNavigateLesson(id);}else{if(!FEATURES.includes(id))return;if(typeof options.onNavigateFeature==='function')await options.onNavigateFeature(id);else if(env.location)env.location.hash='#'+id;else notice(t('unavailable'));}}
    function clear(){clearPending=false;let committed=false;try{if(!storage)throw Error('No storage');storage.removeItem(KEY);committed=storage.getItem(KEY)===null;}catch{}if(committed){progress=initial();level='all';storageState='saved';rawCorrupt=null;}else storageState=storageState==='corrupt'?'corrupt':'volatile';draw();notice(t(committed?'cleared':storageState));return {committed,storageState};}
    function exportProgress(settings={}){const payload={schema:1,exportedAt:new Date().toISOString(),curriculumRevision:data?.revision||null,progress:clone(progress),storageState};if(rawCorrupt!==null){payload.preservedUnreadableProgress=rawCorrupt.slice(0,131072);payload.preservedUnreadableProgressTruncated=rawCorrupt.length>131072;}if(settings.download===false)return payload;let url;try{const blob=new env.Blob([JSON.stringify(payload,null,2)],{type:'application/json'});url=env.URL.createObjectURL(blob);const link=env.document.createElement('a');link.href=url;link.download='Silvio-learning-path-progress.json';link.click();env.setTimeout(()=>env.URL.revokeObjectURL(url),1000);}catch{if(url)env.URL?.revokeObjectURL?.(url);notice(t('exportFail'));}return payload;}
    async function click(event){const el=event.target.closest?.('[data-cu-select],[data-cu-level],[data-cu-action],[data-cu-step],[data-cu-lesson],[data-cu-feature]');if(!el||el.disabled||!host?.contains(el))return;event.preventDefault();try{if(el.dataset.cuSelect)return select(el.dataset.cuSelect);if(el.dataset.cuLevel&&LEVELS.includes(el.dataset.cuLevel)){level=el.dataset.cuLevel;progress.level=level;persist();draw();host?.querySelector?.('[data-cu-level="'+level+'"]')?.focus?.({preventScroll:true});return;}if(el.dataset.cuStep!==undefined&&find()){const step=Number(el.dataset.cuStep);if(!Number.isInteger(step)||step<0||step>2)return;progress.stages[selectedId]={...record(selectedId),step};touch();draw();host?.querySelector?.('[data-cu-step="'+step+'"]')?.focus?.({preventScroll:true});return;}if(el.dataset.cuLesson)return await navigate('lesson',el.dataset.cuLesson);if(el.dataset.cuFeature)return await navigate('feature',el.dataset.cuFeature);switch(el.dataset.cuAction){case'back':selectedId=null;clearPending=false;draw();break;case'sources':host.querySelector?.('#svcu-sources')?.scrollIntoView?.({behavior:env.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches?'auto':'smooth',block:'start'});break;case'complete':{if(!find())break;const p=record(selectedId);if(!p.reviewed&&!p.completed){notice(t('checkFirst'));break;}progress.stages[selectedId]={...p,completed:!p.completed};touch();draw();break;}case'export':exportProgress();break;case'clear':clearPending=true;draw();host?.querySelector?.('[data-cu-action="confirm-clear"]')?.focus?.({preventScroll:true});break;case'cancel-clear':clearPending=false;draw();host?.querySelector?.('[data-cu-action="clear"]')?.focus?.({preventScroll:true});break;case'confirm-clear':if(clearPending)clear();break;}}catch{notice(t('unavailable'));}}
    function change(event){if(!find()||!event.target?.matches?.('[data-cu-reviewed]')||!host?.contains(event.target))return;const reviewed=event.target.checked===true,p=record(selectedId);progress.stages[selectedId]={...p,reviewed,completed:reviewed&&p.completed};touch();draw();host?.querySelector?.('[data-cu-reviewed]')?.focus?.({preventScroll:true});}
    function unmount(){if(!host)return;host.removeEventListener('click',click);host.removeEventListener('change',change);host=null;}
    function mount(element,settings={}){unmount();host=element;if(!host)return;lang=LANGS.includes(settings.lang)?settings.lang:'zh';host.addEventListener('click',click);host.addEventListener('change',change);draw();}
    return Object.freeze({render:()=>'<div id="curriculum-host"></div>',mount,unmount,select,clear,export:exportProgress,state:()=>clone({selectedId,level,lang,storageState,progress,clearPending,dataReady:!!data})});
  }
  return Object.freeze({create,KEY,LANGS,LEVELS,text,safeURL,validateData,validateProgress});
});
